let company={sales:[{name:"John",salary:1e3},{name:"Alice",salary:600}],development:{web:[{name:"Peter",salary:2e3},{name:"Alex",salary:1800}],internals:[{name:"Jack",salary:1300}]}};function sumSalaries(a){let e=0;for(let r in a){let l=a[r];Array.isArray(l)?l.forEach((function(a){e+=a.salary})):e+=sumSalaries(l)}return e}